// Package recorderfixtures embeds the golden replay chunks emitted by the real
// browser recorder (packages/browser/src/replay/recorder.ts) over a scripted
// page. The files are generated by packages/browser/test/replay-wire.test.ts
// (which fails if the recorder's output drifts from them) and consumed by the Go
// validator and chain reader tests, so the two languages cannot disagree about
// the wire silently. Regenerate after an intentional change:
//
//	SOUNDPOST_UPDATE_RECORDER_FIXTURES=1 bun test packages/browser/test/replay-wire.test.ts
package recorderfixtures

import (
	"bytes"
	"embed"
	"encoding/json"
	"fmt"

	"soundpost/internal/model"
)

//go:embed session recovery
var files embed.FS

// Names lists the recorded scenarios.
var Names = []string{"session", "recovery"}

// Scenario is one recorded replay: Wire[i] is the exact JSON the recorder emitted
// as chunk i+1. Delivered[i] is false for a chunk the recorder's sink refused, so
// a receiver never saw it (the recorder then healed the hole with a gap checkpoint).
type Scenario struct {
	Name      string
	Wire      [][]byte
	Delivered []bool
}

// Load returns one recorded scenario.
func Load(name string) (Scenario, error) {
	raw, err := files.ReadFile(name + "/manifest.json")
	if err != nil {
		return Scenario{}, err
	}
	var manifest struct {
		Scenario    string   `json:"scenario"`
		Chunks      []string `json:"chunks"`
		Undelivered []string `json:"undelivered"`
	}
	if err = json.Unmarshal(raw, &manifest); err != nil || manifest.Scenario != name {
		return Scenario{}, fmt.Errorf("recorder fixture %s: bad manifest", name)
	}
	out := Scenario{Name: name, Delivered: make([]bool, len(manifest.Chunks))}
	for i, chunk := range manifest.Chunks {
		body, err := files.ReadFile(name + "/" + chunk)
		if err != nil {
			return Scenario{}, err
		}
		out.Wire = append(out.Wire, bytes.TrimSuffix(body, []byte("\n")))
		out.Delivered[i] = true
		for _, lost := range manifest.Undelivered {
			if lost == chunk {
				out.Delivered[i] = false
			}
		}
	}
	return out, nil
}

// Chunks strictly decodes every wire chunk exactly as the server does
// (model.StrictJSON: unknown fields and duplicate keys are refused).
func (s Scenario) Chunks() ([]model.ReplayChunk, error) {
	out := make([]model.ReplayChunk, len(s.Wire))
	for i, wire := range s.Wire {
		if err := model.StrictJSON(wire, &out[i]); err != nil {
			return nil, fmt.Errorf("recorder fixture %s chunk %d: %w", s.Name, i+1, err)
		}
	}
	return out, nil
}
